			return DataViewColumn.Wrap(WxKitNative.DataViewCtrlPrependToggleColumnStringUIntDataViewCellModeIntAlignmentDataViewColumnFlags(Native, labelText, NativeString.Length(label), checked((uint)modelColumn), (int)mode, width, (int)align, (int)flags));
		}
	}

	/// <summary>Prepends a column for rendering a toggle.</summary>
	public DataViewColumn? PrependToggleColumn(Bitmap label, int modelColumn, DataViewCellMode mode = DataViewCellMode.Inert, int width = 30, Alignment align = Alignment.Center, DataViewColumnFlags flags = DataViewColumnFlags.Resizable) {
		ArgumentNullException.ThrowIfNull(label);
		return DataViewColumn.Wrap(WxKitNative.DataViewCtrlPrependToggleColumnBitmapUIntDataViewCellModeIntAlignmentDataViewColumnFlags(Native, label.Native, checked((uint)modelColumn), (int)mode, width, (int)align, (int)flags));
	}

	/// <summary>Select the given item.</summary>
	public void Select(DataViewItem item) => WxKitNative.DataViewCtrlSelect(Native, item.Value);

	/// <summary>Select all items.</summary>
	public void SelectAll() => WxKitNative.DataViewCtrlSelectAll(Native);

	/// <summary>Set custom colour for the alternate rows used with wxDV_ROW_LINES style.</summary>
	public bool SetAlternateRowColor(Color? color) => WxKitNative.DataViewCtrlSetAlternateRowColour(Native, global::WxKit.Color.ToNative(color)) != 0;

	/// <summary>Sets the row height.</summary>
	public bool SetRowHeight(int rowHeight) => WxKitNative.DataViewCtrlSetRowHeight(Native, rowHeight) != 0;

	/// <summary>Toggle sorting by the given column.</summary>
	public void ToggleSortByColumn(int column) => WxKitNative.DataViewCtrlToggleSortByColumn(Native, column);

	/// <summary>Unselect the given item.</summary>
	public void Unselect(DataViewItem item) => WxKitNative.DataViewCtrlUnselect(Native, item.Value);

	/// <summary>Unselect all item.</summary>
	public void UnselectAll() => WxKitNative.DataViewCtrlUnselectAll(Native);

	private static WxkWindow* CreateNative(Window parent, int id, Point? position, Size? size, DataViewCtrlStyle style) {
		Application.VerifyAccess();
		ArgumentNullException.ThrowIfNull(parent);
		return WxKitNative.DataViewCtrlNew((WxkWindow*)parent.Native, id, position ?? global::WxKit.Point.Default, size ?? global::WxKit.Size.Default, (long)style);
	}
}
